// Writes the references of the protobase agent skill, packages/cli/skills/protobase/references/, from the docs site's
// pages: one Markdown file per page of the sidebar, with links between pages made relative and the rest absolute to
// https://docs.protobase.net. packages/cli/skills/protobase/SKILL.md is written by hand; here it is only checked: every
// generated file needs a pointer in it and every reference link in it needs a file. `protobase skill install` copies the
// skill out of @protobase/cli. With --check nothing is written and it fails when the committed files differ from what
// would be written, which CI runs so the skill cannot fall behind the docs.
//
//   bun run docs:skill [--check]
import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, join, posix } from 'node:path'
import { pageMarkdown } from '../website/src/markdown/page-markdown'
import { guides, reference, startHere } from '../website/sidebar.mjs'

const root = join(import.meta.dir, '..')
const docsDir = join(root, 'website/src/content/docs')
const skillDir = join(root, 'packages/cli/skills/protobase')
const referencesDir = join(skillDir, 'references')
const docsOrigin = 'https://docs.protobase.net'

interface Page {
  path: string
  file: string
  markdown: string
}

async function readPage(path: string): Promise<Page> {
  const filePath = await existing(join(docsDir, `${path}.md`), join(docsDir, `${path}.mdx`))
  const text = await readFile(filePath, 'utf8')
  const match = text.match(/^---\n([\s\S]*?)\n---\n/)
  if (!match?.[1]) throw new Error(`${path} has no frontmatter`)
  const { title, description } = Bun.YAML.parse(match[1]) as { title?: string; description?: string }
  if (!title || !description) throw new Error(`${path} needs a title and a description`)
  const markdown = pageMarkdown({ title, description, body: text.slice(match[0].length), filePath })
  return { path, file: filePath.slice(docsDir.length + 1), markdown }
}

const existing = async (...paths: string[]) => {
  for (const path of paths) if (await Bun.file(path).exists()) return path
  throw new Error(`no page at ${paths.join(' or ')}`)
}

// A page's text with its links to other pages made relative to its own file, and the other links absolute. Lines
// inside fenced blocks stay as they are.
function linked(page: Page, paths: Set<string>) {
  const from = posix.dirname(`${page.path}.md`)
  const link = (_: string, target: string, anchor = '') => {
    const path = target.replace(/\/$/, '')
    if (!paths.has(path)) return `](${docsOrigin}/${target}${anchor})`
    return `](${posix.relative(from, `${path}.md`)}${anchor})`
  }
  let fence: string | undefined
  return page.markdown
    .split('\n')
    .map((line) => {
      const fenceMark = line.trim().match(/^(`{3,}|~{3,})/)?.[1]
      if (fence) {
        if (fenceMark?.startsWith(fence)) fence = undefined
        return line
      }
      if (fenceMark) {
        fence = fenceMark
        return line
      }
      return line.replace(/\]\(\/([^)#]*)(#[^)]*)?\)/g, (match, target, anchor) => `${link(match, target, anchor)})`)
    })
    .join('\n')
}

async function markdownFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { withFileTypes: true }).catch(() => [])
  const nested = await Promise.all(entries.map((entry) => (entry.isDirectory() ? markdownFiles(join(dir, entry.name)) : [join(dir, entry.name)])))
  return nested.flat().filter((file) => file.endsWith('.md'))
}

const pages = await Promise.all([...startHere, ...guides, ...reference].map(readPage))
const paths = new Set(pages.map((page) => page.path))
const expected = new Map(
  pages.map((page) => [
    join(referencesDir, `${page.path}.md`),
    `<!-- Generated by scripts/protobase-skill.ts from website/src/content/docs/${page.file}: run \`bun run docs:skill\`, do not edit. -->\n\n${linked(page, paths)}`,
  ]),
)

const problems: string[] = []

// The hand-written SKILL.md and the generated files must point at each other.
const core = await readFile(join(skillDir, 'SKILL.md'), 'utf8')
const pointed = new Set([...core.matchAll(/\]\((references\/[^)#]*\.md)(?:#[^)]*)?\)/g)].map((match) => join(skillDir, match[1]!)))
for (const file of pointed) {
  if (!expected.has(file)) problems.push(`packages/cli/skills/protobase/SKILL.md links ${file.slice(skillDir.length + 1)}, which is not a generated page: fix the link`)
}
for (const file of expected.keys()) {
  if (!pointed.has(file)) problems.push(`${file.slice(skillDir.length + 1)} has no pointer: add a pointer to it in packages/cli/skills/protobase/SKILL.md`)
}

if (process.argv.includes('--check')) {
  const onDisk = await markdownFiles(referencesDir)
  for (const [file, text] of expected) {
    const committed = await readFile(file, 'utf8').catch(() => undefined)
    if (committed === undefined) problems.push(`${file.slice(root.length + 1)} is missing: run \`bun run docs:skill\` and commit it`)
    else if (committed !== text) problems.push(`${file.slice(root.length + 1)} does not match the docs: run \`bun run docs:skill\` and commit it`)
  }
  for (const file of onDisk) {
    if (!expected.has(file)) problems.push(`${file.slice(root.length + 1)} is not in the sidebar any more: run \`bun run docs:skill\` and commit it`)
  }
  if (problems.length) {
    console.error(problems.join('\n'))
    process.exit(1)
  }
} else {
  await rm(referencesDir, { recursive: true, force: true })
  for (const [file, text] of expected) {
    await mkdir(dirname(file), { recursive: true })
    await writeFile(file, text)
  }
  console.log(`${expected.size} reference pages in packages/cli/skills/protobase/references`)
  if (problems.length) {
    console.error(problems.join('\n'))
    process.exit(1)
  }
}
